108	// Python's sorted() comparison for mapping keys (yaml.dump sorts keys by
109	// default). Mixed incomparable types throw, like CPython's TypeError.
110	export function pythonKeyCompare(a, b) {
111	  const rank = (v) => {
112	    if (typeof v === 'boolean') return 0;
113	    if (typeof v === 'number' || typeof v === 'bigint') return 0;
114	    if (typeof v === 'string') return 1;
115	    if (v instanceof YamlDateTime) return 2;
116	    if (v instanceof YamlDate) return 3;
117	    if (v === null) return 4;
118	    return 5;
119	  };
120	  const ra = rank(a);
121	  const rb = rank(b);
122	  if (ra !== rb) throw new YamlError("'<' not supported between instances of mapping keys");
123	  if (ra === 0) {
124	    const na = typeof a === 'boolean' ? (a ? 1 : 0) : Number(a);
125	    const nb = typeof b === 'boolean' ? (b ? 1 : 0) : Number(b);
126	    return na < nb ? -1 : na > nb ? 1 : 0;
127	  }
128	  if (ra === 1) return a < b ? -1 : a > b ? 1 : 0;
129	  if (ra === 2 || ra === 3) {
130	    const sa = dateTimeToString(a);
131	    const sb = dateTimeToString(b);
132	    return sa < sb ? -1 : sa > sb ? 1 : 0;
133	  }
134	  return 0;
135	}
